import { createGlobalStyle } from "styled-components";

export const GlobalStyle = createGlobalStyle`
    *{
        margin: 0;
        padding: 0;
        box-sizing: border-box;
    }
    h1{
        margin: 0;
    }
    a{
        color: #000;
        text-decoration: none;
        &:hover{
            text-decoration: underline;
        }
    }
`